import{_ as r,l,o as e,c as n,v as i,p,x as o,d as s,i as h,S as P}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"CPO Conservative DPO","description":"","frontmatter":{"title":"CPO Conservative DPO","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/cpo-dpo.md","filePath":"llm/cpo-dpo.md","lastUpdated":1789023840000}'),O={name:"llm/cpo-dpo.md"};function c(m,a,D,d,v,E){const t=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=i('<h1 id="cpo-conservative-dpo" tabindex="-1">CPO Conservative DPO <a class="header-anchor" href="#cpo-conservative-dpo" aria-label="Permalink to &quot;CPO Conservative DPO&quot;">​</a></h1><div class="epigraph"><p>标签会翻面：不要把成对胜率的训练目标钉在 1 上；平滑到 $1-\\varepsilon$，梯度在模型已经给出相应置信度时就可以为零。</p><footer>—— Mitchell，A note on DPO with noisy preferences &amp; relationship to IPO，2023</footer></div><p><a href="/llm/dpo">DPO</a> 把 Bradley–Terry 写成二元交叉熵，目标胜率恒为 1：无论隐含间隔已经多大，logistic 仍给出同号梯度。<a href="/llm/ipo">IPO</a> 用平方损失把间隔钉在有限值上。Eric Mitchell 在 DPO 作者立场上写了一则短注（2023-11-25）：若偏好标签以概率 \\(\\varepsilon\\) 翻面，BCE 的目标应改成 \\(1-\\varepsilon\\)，得到保守 DPO（conservative DPO，cDPO / CPO）。它与 IPO 都能在达到设定之后停下来甚至反号，但停下的对象不同——一个是隐含<strong>胜率</strong>，一个是隐含<strong>奖励间隔</strong>。本篇钉这则笔记的公式与和 IPO 的对照；不要与 Xu 等人机器翻译上的 Contrastive Preference Optimization（TRL 里也叫 CPO）重名混淆，也不要与后来带约束的 Constrained Preference Optimization 混名。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准 DPO 损失是</p> \\[\\mathcal{L}_{\\mathrm{DPO}}=-\\log\\sigma(\\beta h),\\qquad h=\\log\\frac{\\pi_\\theta(y_w)}{\\pi_{\\mathrm{ref}}(y_w)}-\\log\\frac{\\pi_\\theta(y_l)}{\\pi_{\\mathrm{ref}}(y_l)}, \\]<p>即 \\(\\hat p=\\sigma(\\beta h)\\) 对目标 \\(p=1\\) 的 BCE。人的比较有噪声：心情、长度、界面顺序都会翻面。把每条标签当成确定事件，模型会为错误的赢方持续加间隔，直到数值崩坏；即使标签正确，「确定赢」在 BT 里对应无穷奖励差，KL 正则相对失效——这与 Azar 对 logit \\(\\Psi\\) 的批评同一机制，见 <a href="/llm/azar-ipo">IPO 原文</a>。</p><p>分类里对付标签噪声的经典手段是 label smoothing：目标从 one-hot 改成 \\(1-\\varepsilon\\)。偏好是二元分类的特例。问题是：把同一平滑写进 DPO 之后，零梯度条件变成什么，它和 IPO 的 \\(h=1/(2\\tau)\\) 是不是一回事。</p><h3 id="未平滑-dpo-的梯度永不精确为零" tabindex="-1">未平滑 DPO 的梯度永不精确为零 <a class="header-anchor" href="#未平滑-dpo-的梯度永不精确为零" aria-label="Permalink to &quot;未平滑 DPO 的梯度永不精确为零&quot;">​</a></h3><p>\\(\\sigma(\\beta h)\\to 1\\) 时梯度趋于 0，但只在 \\(h\\to+\\infty\\) 时达到。有限训练步里，损失永远在说「再拉开一点」。噪声对与正确对共用这一不饱和方向。平滑之后，目标不再是无穷置信，才可能在有限 \\(h\\) 处真正停住。</p><p><span class="marginnote">\\(\\varepsilon\\) 是对标注过程的模型，不是学习率。它应来自重复标注一致率或对噪声的先验，而不是从 DPO 的 \\(\\beta\\) 网格里抄一个小数。设错 \\(\\varepsilon\\) 等于设错应达到的胜率。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>令目标 \\(p(y_w\\succ y_l)=1-\\varepsilon\\)，\\(\\varepsilon\\in(0,0.5)\\)。平滑 BCE 为</p> \\[\\mathcal{L}_\\varepsilon=-(1-\\varepsilon)\\log\\hat p-\\varepsilon\\log(1-\\hat p) =(1-\\varepsilon)\\mathcal{L}_{\\mathrm{DPO}}(\\theta;y_w,y_l)+\\varepsilon\\mathcal{L}_{\\mathrm{DPO}}(\\theta;y_l,y_w). \\]<p>第二行给出实现：以 \\(1-\\varepsilon\\) 与 \\(\\varepsilon\\) 的权重，同时走正向 DPO 与把输赢对调的 DPO。梯度（忽略与 \\(\\pi_{\\mathrm{ref}}\\) 有关的常数项，笔记写法）满足</p> \\[\\nabla\\mathcal{L}_\\varepsilon \\propto \\bigl(\\hat p-(1-\\varepsilon)\\bigr)\\bigl(\\nabla\\log\\pi_\\theta(y_w)-\\nabla\\log\\pi_\\theta(y_l)\\bigr). \\]<p>\\(\\hat p=1-\\varepsilon\\) 时梯度为零。BT 下这对应有限的 \\(\\beta h=\\mathrm{logit}(1-\\varepsilon)\\)，而不是无穷间隔。</p><h3 id="和-ipo-零点的差别" tabindex="-1">和 IPO 零点的差别 <a class="header-anchor" href="#和-ipo-零点的差别" aria-label="Permalink to &quot;和 IPO 零点的差别&quot;">​</a></h3><p>IPO 的梯度正比于 \\(h-1/(2\\tau)\\)，零点在<strong>奖励差</strong>（对数比差）上。cDPO 的零点在 <strong>\\(\\sigma(\\beta h)\\)</strong> 上。同一 \\(\\beta\\)，两种零点一般不重合：\\(\\sigma(\\beta h)=1-\\varepsilon\\) 解出的 \\(h\\) 与 \\(1/(2\\tau)\\) 只有在特意对齐 \\(\\varepsilon\\) 与 \\(\\tau\\) 时才相等。笔记的 TL;DR：cDPO 训练到对这条样本的隐含偏好概率达到 \\(1-\\varepsilon\\)；IPO 训练到隐含奖励达到设定间隔。两者都能在达标后停止或反向，因而都比原始 DPO 更能在长训练后保持稳定。</p>',19)),(e(),p(P,null,{default:o(()=>[h(t,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAB%5B%22%E8%A7%82%E5%AF%9F%E5%88%B0%20yw%20%E2%89%BB%20yl%22%5D%20--%3E%20NOISE%5B%22%E6%A0%87%E7%AD%BE%E4%BB%A5%20%CE%B5%20%E7%BF%BB%E9%9D%A2%22%5D%0A%20%20NOISE%20--%3E%20TGT%5B%22%E7%9B%AE%E6%A0%87%E8%83%9C%E7%8E%87%201-%CE%B5%22%5D%0A%20%20TGT%20--%3E%20BCE%5B%22%E5%B9%B3%E6%BB%91%20BCE%20%2F%20%E6%AD%A3%E5%8F%8D%E5%90%91%20DPO%20%E6%B7%B7%E5%90%88%22%5D%0A%20%20BCE%20--%3E%20Z%5B%22%E2%88%87%3D0%20%E5%BD%93%20%CF%83(%CE%B2h)%3D1-%CE%B5%22%5D%0A%20%20IPO%5B%22IPO%22%5D%20--%3E%20Z2%5B%22%E2%88%87%3D0%20%E5%BD%93%20h%3D1%2F(2%CF%84)%22%5D%0A%20%20DPO%5B%22%E5%8E%9F%E5%A7%8B%20DPO%22%5D%20--%3E%20INF%5B%22%E4%BB%85%E5%BD%93%20h%E2%86%92%E2%88%9E%20%E6%89%8D%E9%A5%B1%E5%92%8C%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h3 id="实现与命名" tabindex="-1">实现与命名 <a class="header-anchor" href="#实现与命名" aria-label="Permalink to &quot;实现与命名&quot;">​</a></h3><p>TRL 一类库把 label smoothing 做成 DPO 的开关，有的文档写作 cDPO 或 robust DPO。这与 Xu 等 <em>Contrastive Preference Optimization</em>（翻译任务上、常加 NLL、常无参照）不是同一篇论文，尽管缩写都是 CPO。评审或配置文件里应写「conservative DPO, Mitchell 2023, \\(\\varepsilon=\\)…」，而不是只写 CPO。笔记本身没有大规模聊天实验，经验数字来自后续复现：\\(\\varepsilon\\) 常用 \\(0.1\\) 量级，须在持有比较与原能力上扫。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>平滑是在概率空间封顶。模型对一条训练对的 \\(\\hat p\\) 一旦到 \\(1-\\varepsilon\\)，即使标签仍写「赢」，也不再加间隔；若过冲，反向 DPO 项会把间隔拉回来。这直接限制噪声对的伤害上限（在这一项上）。它不修正系统捷径：若 80% 的对都是更长的赢，目标胜率 \\(1-\\varepsilon\\) 仍一致要求更长的一边 \\(\\hat p\\) 高。cDPO 抑制的是无限自信，不是长度黑客。</p><p>相对 IPO，cDPO 留在 logistic / BT 几何里，只改目标标签；IPO 改的是 \\(\\Psi\\) 与损失族。若你相信比较近似 BT、只是标签有对称翻面，平滑是对症的噪声模型。若你不相信 logit 标度（确定比较应对应无穷 \\(r\\)），应改 \\(\\Psi\\)，那是 IPO。两条可以同时做，但那时超参 \\(\\varepsilon\\) 与 \\(\\tau\\) 的含义重叠，必须只留一个主旋钮，避免「平滑了又回归间隔」的双重封顶把策略钉死在参照附近。</p><p><span class="marginnote">\\(\\varepsilon\\to 0\\) 恢复 DPO；\\(\\varepsilon\\to 0.5\\) 目标胜率 \\(0.5\\)，梯度在 \\(\\hat p=0.5\\) 即 \\(h=0\\) 处为零，等于不学偏好。\\(\\varepsilon\\) 过大会把有效信号洗掉，不是越保守越好。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>笔记是两页推导，没有声称在 HH 或 AlpacaEval 上超过 DPO。把它当完整算法论文会过读。\\(\\varepsilon\\) 假定翻面对称、与样本无关；真实噪声往往是长度、位置、特定提示上的系统偏差，平滑只处理随机翻面这一层。重复标注可以得到经验翻面率，用来标定 \\(\\varepsilon\\)；多数开源偏好集没有重复标注，此时 \\(\\varepsilon\\) 只是保守先验，不是测出来的噪声水平。没有参照时写不出 \\(h\\)，cDPO 仍是带 \\(\\pi_{\\mathrm{ref}}\\) 的 DPO 变体，省不了第二份前向。平滑改变的是标签目标，不改变对数概率的归约方式：训练若对 token 平均、评估却用求和，零点对应的物理间隔会跟着变，配方里仍要写死。</p><p>不要和 Constrained Preference Optimization、Chain-of-Preference Optimization、Contrastive Preference Optimization 混引。需要无参考对比，看 ORPO / SimPO；需要不成对，看 KTO；需要有限间隔且改 \\(\\Psi\\)，看 IPO。cDPO 的位置极窄：已经在跑 DPO，怀疑标签噪声，想在同一 BT 损失里给目标胜率封顶。</p><p><span class="marginnote">出处钉 Eric Mitchell，<em>A note on DPO with noisy preferences &amp; relationship to IPO</em>，2023，ericmitchell.ai/cdpo.pdf。DPO 原文作者之一以注释形式给出，不是独立会议长文。引用应同时指向 Rafailov 等 DPO 与 Azar 等 IPO。</span></p><h3 id="何时不必上-cdpo" tabindex="-1">何时不必上 cDPO <a class="header-anchor" href="#何时不必上-cdpo" aria-label="Permalink to &quot;何时不必上 cDPO&quot;">​</a></h3><p>标签很干净、训练步数短、尚未看到间隔过拟合，标准 DPO 即可。已经改用 IPO 的平方损失，通常不必再叠一层 \\(\\varepsilon\\)。噪声来自捷径而不是随机翻面，先洗数据。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Conservative DPO 把 DPO 的 BCE 目标从 1 改成 \\(1-\\varepsilon\\)，等价于正反向 DPO 的凸组合。</li><li>梯度在 \\(\\sigma(\\beta h)=1-\\varepsilon\\) 时为零：有限置信，而非无穷间隔。</li><li>IPO 停在奖励差，cDPO 停在偏好概率；两者都能避免原始 DPO 永不饱和。</li><li>只建模对称翻面；系统捷径与无参照设定不在这篇笔记里。</li><li>缩写 CPO 与至少三种其他算法撞名，配置里应写全称与 \\(\\varepsilon\\)。</li><li>出处：Mitchell，2023 年关于 noisy preferences 的 DPO 注释；对照 Rafailov 等 DPO、Azar 等 IPO。</li></ul>',14))])}const f=r(O,[["render",c]]);export{B as __pageData,f as default};
